// Кейс: .qa/tests/shop/SHOP-004.md · план: .qa/e2e-app/specs/app.md (1.3)
// Только появление системного окна iOS «открыть WhatsApp» и «Отменить». Чат WhatsApp НЕ открывается, сообщение не отправляется.
import { by, assert, CANCEL, APP_BUNDLE_ID } from '../../lib/appium.mjs';
import { onHome, openTab } from '../../lib/banci.mjs';

export const name = 'Товар → «פנייה לרכישה בוואטסאפ» → системное окно «открыть WhatsApp» → Отменить #c48aff34 @iphone @app @prod-safe';

const PRODUCT = process.env.BANCI_PRODUCT || 'מצופי ידיים לילדים'; // товар с номером поставщика (проверен 18.10)

export default async function (app) {
  // 1. «חשבון» → «מוצרים לבריכה» → товар.
  await onHome(app);
  await openTab(app, 'חשבון');
  const entry = await app.scrollTo(by.begins('מוצרים לבריכה'), { what: 'пункт «מוצרים לבריכה» в «חשבון»' });
  await entry.click();
  const product = await app.scrollTo(by.contains(PRODUCT), { what: `товар «${PRODUCT}»` });
  await product.click();

  // 2. Кнопка «פנייה לרכישה בוואטסאפ» активна → нажать.
  const btn = await app.scrollTo('(name CONTAINS "פנייה" OR label CONTAINS "פנייה") AND (name CONTAINS "וואטסאפ" OR label CONTAINS "וואטסאפ")', { what: 'кнопка «פנייה לרכישה בוואטסאפ»' });
  assert(await btn.enabled(), 'кнопка «פנייה לרכישה בוואטסאפ» активна (у поставщика есть номер)');
  await btn.click();

  // 3. Системное окно iOS «открыть в WhatsApp» (текст на языке телефона).
  const alert = await app.waitAlert({ timeout: 10000 });
  assert(/whatsapp|וואטסאפ/i.test(alert.text), `окно про WhatsApp (текст: «${alert.text}»)`);
  assert(alert.buttons.some((b) => CANCEL.test(b)), `в окне есть кнопка отмены (кнопки: ${alert.buttons.join(' / ')})`);

  // 4. Отменить — WhatsApp не открывается, остаёмся на товаре.
  const res = await app.cancelAlert();
  assert(res?.pressed, 'нажата кнопка отмены');
  assert(!(await app.alert()), 'системное окно закрыто');
  assert((await app.appState(APP_BUNDLE_ID)) === 4, 'Banci на переднем плане (WhatsApp не открыт)');
  assert(await app.exists('(name CONTAINS "פנייה" OR label CONTAINS "פנייה") AND (name CONTAINS "וואטסאפ" OR label CONTAINS "וואטסאפ")'), 'страница товара на месте');
}
